private readonly object gate = new();
private readonly Queue<int> q = new();
public int Take() {
    lock (gate) {
        while (q.Count == 0) Monitor.Wait(gate);   // release + park + re-acquire
        return q.Dequeue();
    }
}

public void Put(int v) {
    lock (gate) { q.Enqueue(v); Monitor.PulseAll(gate); }   // change, then notify
}

