private readonly SemaphoreSlim slots = new(0);

public async Task<int> TakeAsync(CancellationToken ct)
{
    await slots.WaitAsync(ct);            // suspends the task, not a thread
    lock (gate) return q.Dequeue();       // the permit was the guard
}
public void Put(int v)
{
    lock (gate) q.Enqueue(v);             // change state first
    slots.Release();                      // then signal availability
}
